def omega(n):
    cnt = 0
    m = n
    d = 2
    while d * d <= m:
        if m % d == 0:
            cnt += 1
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        cnt += 1
    return cnt

EXPECTED_COUNT = 0
EXPECTED_CHECKSUM = 0

def recompute():
    S = []
    for n in range(1, 9699690):
        ok = True
        for j in (1, 2, 3, 4, 5, 6, 7, 8):
            if omega(n - j) > j:
                ok = False
                break
        if ok:
            S.append(n)
    return S

def verify():
    S = recompute()
    if len(S) != EXPECTED_COUNT:
        return False
    chk = 0
    for n in S:
        chk = (chk * 1000003 + n) % 2305843009213693951
        for j in (1, 2, 3, 4, 5, 6, 7, 8):
            if omega(n - j) > j:
                return False
    return chk == EXPECTED_CHECKSUM

def main():
    if verify():
        return 0
    return 1
